            {/* 노선도 그래픽 (수직선 + 점) */}
            <div className="absolute left-9 top-1/2 -translate-y-1/2 w-0.5 h-[60%] bg-indigo-100" />
            <div className="flex flex-col justify-between py-1 relative z-10 w-6 items-center">
