            disabled={isLoggingIn}
            className={`mt-10 flex w-full items-center justify-center gap-2.5 rounded-2xl border border-gray-200 bg-white py-3.5 text-base font-semibold text-gray-800 shadow-sm transition-all hover:border-purple-300 hover:bg-gray-50 active:scale-95 sm:mt-12 sm:gap-3 sm:py-4 sm:text-lg ${isLoggingIn ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {isLoggingIn ? (
              <div className="h-6 w-6 animate-spin rounded-full border-2 border-gray-300 border-t-indigo-600"></div>
            ) : (
              <svg className="h-6 w-6 shrink-0" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                <path
                  d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                  fill="#4285F4"
                />
                <path
                  d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                  fill="#34A853"
                />
                <path
                  d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                  fill="#FBBC05"
                />
                <path
                  d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                  fill="#EA4335"
                />
              </svg>
            )}
            {isLoggingIn ? 'Connecting...' : 'Continue with Google'}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { LogOut, ChevronRight, CarTaxiFront } from 'lucide-react';
import BottomNav from '../components/BottomNav';
import { createClient } from '@/lib/supabase/client';

export default function ProfilePage() {
  const router = useRouter();
  const [supabase] = useState(() => (typeof window === 'undefined' ? null : createClient()));
  const [myPods, setMyPods] = useState<any[]>([]);
  const [displayName, setDisplayName] = useState('Guest');
  const [displayRole, setDisplayRole] = useState('—');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!supabase) return;
    const fetchData = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        router.replace('/');
        return;
      }

      // 1. Fetch Profile
      const { data: profile } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single();

      if (profile) {
        setDisplayName(profile.nickname || 'User');
        setDisplayRole(profile.role === 'USA_ARMY' ? 'U.S. Army' : 'KATUSA');
      }

      // 2. Fetch My Active Pods (Joined pods that are active)
      const { data: memberships } = await supabase
        .from('pod_members')
        .select(`
          pod:pods!inner (
            *,
            member_count:pod_members(count)
          )
        `)
        .eq('user_id', user.id)
        .eq('pod.status', 'active');

      if (memberships) {
        const now = Date.now();
        const formattedPods = memberships
          .map((m: any) => m.pod)
          .filter(Boolean)
          .map((p: any) => ({
            ...p,
            member_count: p.member_count[0]?.count || 0
          }))
          // 6시간 지난 방은 프로필에서도 제거(그리고 status 만료 처리)
          .filter((p: any) => {
            const ms = new Date(p.departure_time).getTime();
            return Number.isFinite(ms) && ms + 6 * 60 * 60 * 1000 > now;
          })
          .sort((a: any, b: any) => 
            new Date(a.departure_time).getTime() - new Date(b.departure_time).getTime()
          );
        setMyPods(formattedPods);
      }
      setLoading(false);
    };

    fetchData();
  }, [router, supabase]);

  const handleLogout = async () => {
    if (!supabase) return;
    await supabase.auth.signOut();
    router.push('/');
  };

  if (loading) {
    return (
      <div className="flex h-dvh items-center justify-center bg-white">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
      </div>
    );
  }

  return (
    <div className="flex h-dvh flex-col bg-gray-50 font-sans antialiased pb-24">
      <main className="flex min-h-0 flex-1 flex-col gap-6 overflow-y-auto px-6 py-6">
        
        {/* 1. 유저 정보 카드 */}
        <div className="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="flex h-16 w-16 items-center justify-center rounded-full bg-purple-100 text-2xl">
              🧑‍🚀
            </div>
            <div>
              <h2 className="text-xl font-bold text-gray-900">{displayName}</h2>
              <p className="text-sm font-medium text-gray-500">
                {displayRole} • Camp Humphreys
              </p>
            </div>
          </div>
        </div>

        {/* 2. 현재 참여 중인 방 (기획 요소 반영) */}
        <div>
          {myPods.length === 0 ? (
            <div className="rounded-2xl border border-dashed bg-white p-6 text-center text-sm font-semibold text-gray-500">
              No active rooms.
            </div>
          ) : (
            <div className="space-y-3">
              {myPods.map((r) => {
                const timeStr = new Date(r.departure_time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
                const dateStr = new Date(r.departure_time).toLocaleDateString('en-US', { day: '2-digit', month: 'long' });

                return (
                  <div
                    key={r.id}
                    onClick={() => router.push(`/chat/${r.id}`)}
                    className="flex cursor-pointer items-center justify-between rounded-2xl border border-indigo-100 bg-indigo-50 p-5 shadow-sm transition-all hover:border-indigo-300 active:scale-95"
                  >
                    <div className="flex items-center gap-4">
                      <div className="rounded-full bg-indigo-600 p-2.5 text-white">
                        <CarTaxiFront className="h-6 w-6" />
                      </div>
                      <div>
                        <p className="text-sm font-bold text-indigo-600">
                          {r.member_count}/{r.capacity} Members
                        </p>
                        <p className="text-base font-semibold text-gray-900">
                          {r.origin} → {r.destination}
                        </p>
                        <p className="text-xs font-semibold text-gray-500">
                          {dateStr}, {timeStr}
                        </p>
                      </div>
                    </div>
                    <ChevronRight className="h-5 w-5 text-indigo-400" />
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* 3. 메뉴 리스트 (미니멀) */}
        <div className="mt-4 rounded-2xl border border-gray-200 bg-white shadow-sm overflow-hidden">
          <button className="flex w-full items-center justify-between border-b border-gray-100 px-6 py-4 text-left transition-colors hover:bg-gray-50">
            <span className="font-semibold text-gray-700">Payment Methods</span>
            <ChevronRight className="h-5 w-5 text-gray-400" />
          </button>
          <button className="flex w-full items-center justify-between px-6 py-4 text-left transition-colors hover:bg-gray-50">
            <span className="font-semibold text-gray-700">Ride History</span>
            <ChevronRight className="h-5 w-5 text-gray-400" />
          </button>
        </div>

        {/* 4. 로그아웃 버튼 */}
        <button 
          onClick={handleLogout}
          className="mt-6 flex w-full items-center justify-center gap-2 rounded-2xl border border-red-100 bg-red-50 py-4 font-bold text-red-600 transition-colors hover:bg-red-100 active:scale-95"
        >
          <LogOut className="h-5 w-5" />
          Log Out
        </button>

      </main>

      <BottomNav />
    </div>
  );
}

import { createBrowserClient } from '@supabase/ssr'

let client: any = null;

export function createClient() {
  if (!client) {
    const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
    
    if (!url || !key) {
      if (typeof window !== 'undefined') {
        console.error('Supabase URL or Key is missing in browser client creation');
      }
    }
    
    client = createBrowserClient(url!, key!);
  }
  
  return client;
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

export async function updateSession(request: NextRequest) {
  let supabaseResponse = NextResponse.next({
    request,
  })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value, options }) => request.cookies.set(name, value))
          supabaseResponse = NextResponse.next({
            request,
          })
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  // IMPORTANT: Avoid writing any logic between createServerClient and
  // supabase.auth.getUser(). A simple mistake can make it very hard to debug
  // issues with sessions being lost.

  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (
    !user &&
    !request.nextUrl.pathname.startsWith('/signup') &&
    request.nextUrl.pathname !== '/'
  ) {
    // no user, potentially respond by redirecting the user to the login page
    const url = request.nextUrl.clone()
    url.pathname = '/'
    return NextResponse.redirect(url)
  }

  // IMPORTANT: You *must* return the supabaseResponse object as is. If you're creating a
  // new response object with NextResponse.next() make sure to:
  // 1. Pass the request in it, like so:
  //    const myNewResponse = NextResponse.next({ request })
  // 2. Copy over the cookies, like so:
  //    myNewResponse.cookies.setAll(supabaseResponse.cookies.getAll())
  // 3. Change the supabaseResponse object to your new response, like so:
  //    supabaseResponse = myNewResponse
  // 4. Finally, return supabaseResponse
  // If not, you can potentially cause unexpected behavior where the user is logged out after
  // next steps.

  return supabaseResponse
}
